import{_ as s,o as e,c as a,a2 as n}from"./chunks/framework.DqYch1Cg.js";const k=JSON.parse('{"title":"NestJS 服务设计：从需求到接口的最小闭环","description":"","frontmatter":{},"headers":[],"relativePath":"编码与实践/18nestjs/c_nestjs_1-service_design/c_nestjs_1-service_design.md","filePath":"编码与实践/18nestjs/c_nestjs_1-service_design/c_nestjs_1-service_design.md","lastUpdated":1794211306000}'),i={name:"编码与实践/18nestjs/c_nestjs_1-service_design/c_nestjs_1-service_design.md"};function r(d,t,p,l,h,o){return e(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="nestjs-服务设计-从需求到接口的最小闭环" tabindex="-1">NestJS 服务设计：从需求到接口的最小闭环 <a class="header-anchor" href="#nestjs-服务设计-从需求到接口的最小闭环" aria-label="Permalink to &quot;NestJS 服务设计：从需求到接口的最小闭环&quot;">​</a></h1><blockquote><p>状态：设计练习，尚未运行验证。本文把零散课程笔记串成一个可逐步实现的方案，不代表 <a href="https://github.com/Fridolph/AI-Journey-land" target="_blank" rel="noreferrer">AI-Journey-land</a> 已实现这些功能，也不会在本站安装 NestJS 或连接数据库。</p></blockquote><h2 id="先明确要解决的问题" tabindex="-1">先明确要解决的问题 <a class="header-anchor" href="#先明确要解决的问题" aria-label="Permalink to &quot;先明确要解决的问题&quot;">​</a></h2><p>学习过程中，笔记、代码和复盘经常分散在不同地方。第一阶段可以先解决“登录后保存、查看和修改自己的学习笔记”，让一次学习记录能持续积累。</p><p>动手前先写清：用户是谁，最痛的具体问题是什么，完成哪一步才算获得价值，用什么现象判断完成。框架、Redis、AI 都应服务这个目标。</p><p><strong>本轮闭环</strong>：注册 / 登录 → 创建笔记 → 读取和分页查看自己的笔记 → 修改 / 删除 → 验证重启后数据仍存在。</p><p>暂缓后台菜单、多租户、微服务、RAG 和 Agent。Redis 也先按实际需求决定，避免为了“技术栈完整”增加尚未需要的基础设施。</p><h2 id="从业务规则得到模块与技术方案" tabindex="-1">从业务规则得到模块与技术方案 <a class="header-anchor" href="#从业务规则得到模块与技术方案" aria-label="Permalink to &quot;从业务规则得到模块与技术方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>部分</th><th>首轮职责</th><th>边界与选择依据</th></tr></thead><tbody><tr><td>UsersModule</td><td>用户资料、账号持久化</td><td>密码使用合适算法哈希，响应不返回密码哈希</td></tr><tr><td>AuthModule</td><td>登录、身份验证</td><td>区分认证“你是谁”和授权“你能做什么”</td></tr><tr><td>NotesModule</td><td>个人笔记 CRUD</td><td>归属与修改规则放在业务用例中，不仅依赖前端隐藏按钮</td></tr><tr><td>数据访问</td><td>PostgreSQL + 一种 ORM</td><td>跟课可选 TypeORM；也可用 Prisma，首轮不同时维护两套</td></tr><tr><td>配置与日志</td><td>配置校验、requestId、错误记录</td><td>通用机制集中接入，避免每个 Service 重复读取配置</td></tr></tbody></table><p>NestJS + TypeScript 有助于衔接前端经验，Module 与 DI 便于组织和测试。PostgreSQL 用来学习关系约束与并发控制；更详细的选型见<a href="/FE-prepare-interview/学习自测/19database/q_database_1-postgresql_vs_mysql">PostgreSQL 与 MySQL 对比</a>。这些是选择理由，不意味着其他技术不能实现。</p><p>RBAC 角色权限、后台菜单、操作审计可以在业务需要时逐步加入。菜单是展示配置，不能代替服务端接口和资源权限检查。Redis 可用于共享会话、令牌撤销或缓存，但 JWT 验签本身不必每次访问 Redis；如果要求即时下线，就需要额外的会话 / 令牌状态策略。</p><h2 id="先写接口契约-再实现链路" tabindex="-1">先写接口契约，再实现链路 <a class="header-anchor" href="#先写接口契约-再实现链路" aria-label="Permalink to &quot;先写接口契约，再实现链路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接口</th><th>输入要点</th><th>预期结果与边界</th></tr></thead><tbody><tr><td><code>POST /auth/register</code></td><td>邮箱、密码等</td><td>成功 201；重复账号按已定义的业务错误处理；并发重复由唯一约束兜底</td></tr><tr><td><code>POST /auth/login</code></td><td>登录凭据</td><td>成功 200；无效凭据 401；避免通过错误细节枚举账号</td></tr><tr><td><code>POST /notes</code></td><td>标题、内容</td><td>成功 201；归属取自认证上下文，不接受客户端指定其他用户</td></tr><tr><td><code>GET /notes</code></td><td>分页、可选关键词</td><td>成功 200；只查本人数据，限制分页大小并使用稳定排序</td></tr><tr><td><code>GET /notes/:id</code></td><td>笔记 ID</td><td>成功 200；不存在或无权查看时，可统一 404，减少资源信息泄露</td></tr><tr><td><code>PATCH /notes/:id</code></td><td>允许修改的字段、预期版本</td><td>成功 200；本人笔记版本冲突 409；不存在或无权操作按既定策略返回</td></tr><tr><td><code>DELETE /notes/:id</code></td><td>笔记 ID</td><td>成功 204、无响应体；是否支持并发删除保护需明确</td></tr></tbody></table><p>输入格式错误通常返回 400，缺少或无效身份返回 401，已认证但权限不足通常是 403；也可以按资源隐藏策略返回 404，关键是策略一致。Nest 的 POST 默认是 201，登录等需要 200 的路由应显式配置 <code>@HttpCode(200)</code>；删除返回 204 也应明确设置。</p><p>PATCH 的 DTO 应区分“未提供”“空字符串”和 <code>null</code>，不要把可选字段理解成允许清空所有内容；空更新也应提前定义为拒绝还是无操作。错误契约可以包含 <code>code</code>、可公开的 <code>message</code> 与 <code>requestId</code>，不向客户端泄露 SQL、堆栈或密钥。</p><h2 id="沿一次保存请求放置职责" tabindex="-1">沿一次保存请求放置职责 <a class="header-anchor" href="#沿一次保存请求放置职责" aria-label="Permalink to &quot;沿一次保存请求放置职责&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Middleware：生成或校验 requestId</span></span>
<span class="line"><span>  → Guard：校验身份，把可信 userId 放入上下文</span></span>
<span class="line"><span>  → Interceptor（进入）：开始观测本次处理</span></span>
<span class="line"><span>  → Pipe：校验 ID、DTO 与版本号</span></span>
<span class="line"><span>  → Controller：把 userId、id、dto 交给 Service</span></span>
<span class="line"><span>  → Service：检查规则，协调更新与事务</span></span>
<span class="line"><span>  → Repository：执行带归属和版本条件的更新</span></span>
<span class="line"><span>  → Interceptor（返回）：结果转换、记录处理耗时</span></span>
<span class="line"><span>  → 响应；未处理的异常走异常过滤器分支</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>Guard 执行早于参数 Pipe，不能直接假定其中的 ID 或请求体已经被管道转换、校验。依赖业务数据的归属检查可以放在 Service，并将归属条件落实到数据库操作里。</p><p>通用入口、业务规则和持久化的进一步区分见<a href="/FE-prepare-interview/概念与原理/18nestjs/s_nestjs_11-layering_dto_dao">MVC、DTO 与 DAO</a>。</p><h2 id="数据约束和并发设计要一起考虑" tabindex="-1">数据约束和并发设计要一起考虑 <a class="header-anchor" href="#数据约束和并发设计要一起考虑" aria-label="Permalink to &quot;数据约束和并发设计要一起考虑&quot;">​</a></h2><p>第一版可以从两张表开始，具体迁移在练习仓库中再实现：</p><table tabindex="0"><thead><tr><th>表</th><th>建议字段与约束</th><th>对应业务意义</th></tr></thead><tbody><tr><td>users</td><td>主键、规范化邮箱的唯一约束、password_hash</td><td>账号不可重复，不能存明文密码</td></tr><tr><td>notes</td><td>主键、owner_id 外键、title、content、version、时间戳</td><td>记录归属、内容与并发版本</td></tr></tbody></table><p>标题长度、版本号非负等约束可以在适当层次表达。笔记列表按实际过滤与排序评估 <code>(owner_id, created_at, id)</code> 等组合索引，并用执行计划验证；PostgreSQL 不会因为声明了外键就自动为引用列建立索引。用户删除时限制还是级联删除笔记，也要先明确产品规则。</p><p>固定结构先使用普通列。后续出现可变的学习模块再考虑 JSONB，不要因为支持 JSON 就把所有字段放在同一个 JSON 对象里。</p><h3 id="防止两个客户端互相覆盖" tabindex="-1">防止两个客户端互相覆盖 <a class="header-anchor" href="#防止两个客户端互相覆盖" aria-label="Permalink to &quot;防止两个客户端互相覆盖&quot;">​</a></h3><p>仅把“读取 → 修改”放进事务，不一定阻止丢失更新。可以让客户端提交预期版本，在一次 SQL 中完成判断、写入和版本递增：</p><div class="language-sql vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 设计示意：$1～$5 必须通过数据库驱动绑定，不拼接用户输入。</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 此处假设标题和内容已在业务层补齐；实际 PATCH 需保留未提交的字段。</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> notes</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> title </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    content </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    updated_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CURRENT_TIMESTAMP</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> owner_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> version</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RETURNING id, title, content, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, updated_at;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><p>影响零行可能代表不存在、无权操作或版本冲突，不能一概解释为冲突。若需要区分，可按相同归属条件补查并依照契约映射，不能泄露他人笔记是否存在；需要更严格的一致性时，应在合适事务边界内设计锁与判断。客户端遇到 409 应重新获取数据、提示合并或确认覆盖，而不是无脑自动重放旧内容。</p><p>单条更新本身具有原子性。若保存笔记和写业务审计记录要求共同成功，就需要共享事务；缓存与消息不在同一个数据库事务内时，则要另行设计失效与可靠投递，不能靠一个数据库事务自动保证。</p><h2 id="把开发、运维与安全问题变成可检查的约束" tabindex="-1">把开发、运维与安全问题变成可检查的约束 <a class="header-anchor" href="#把开发、运维与安全问题变成可检查的约束" aria-label="Permalink to &quot;把开发、运维与安全问题变成可检查的约束&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方面</th><th>首轮应落实的事情</th><th>容易忽略的边界</th></tr></thead><tbody><tr><td>多环境配置</td><td>开发 / 测试 / 生产隔离；启动时校验必要配置</td><td>不把密钥提交到仓库，不在日志输出连接串；测试不连生产库</td></tr><tr><td>数据访问安全</td><td>参数化查询、最小数据库权限、限制输入体积</td><td>ORM 不能使原始 SQL 拼接自动安全，白名单也不能代替资源授权</td></tr><tr><td>认证与浏览器</td><td>HTTPS；明确令牌存储、有效期与撤销方式</td><td>Cookie 会话要考虑 CSRF；CORS 不是认证，也不阻止所有非浏览器调用</td></tr><tr><td>日志与审计</td><td>requestId、状态码、耗时、必要错误上下文</td><td>过滤 Authorization、密码、敏感笔记内容；访问日志不等于业务审计</td></tr><tr><td>性能与可用性</td><td>分页、索引、连接池上限、外部调用超时</td><td>先观察慢查询、P95 / P99、错误率；限流与缓存按瓶颈加入</td></tr><tr><td>迁移与发布</td><td>审核迁移与兼容窗口，准备备份和恢复流程</td><td>生产不靠 <code>synchronize: true</code> 自动改表；回滚代码不等于回滚数据</td></tr><tr><td>下线与故障</td><td>停止接入新工作、有界等待、释放连接与后台任务</td><td>数据库断线和正常停机不同；写入结果不确定时不能盲目重试</td></tr></tbody></table><p>具体关闭顺序和断线处理继续阅读<a href="/FE-prepare-interview/学习自测/18nestjs/q_nestjs_6-app_lifecycle">应用生命周期与数据库清理</a>。这里描述需要考虑的设计，不修改本站部署、环境变量或数据库配置。</p><h2 id="分成三个可以验收的切片" tabindex="-1">分成三个可以验收的切片 <a class="header-anchor" href="#分成三个可以验收的切片" aria-label="Permalink to &quot;分成三个可以验收的切片&quot;">​</a></h2><table tabindex="0"><thead><tr><th>切片</th><th>要完成什么</th><th>应留下的证据</th></tr></thead><tbody><tr><td>1. 跑通契约</td><td>Controller + DTO + Service + 内存仓储；身份可在测试中模拟</td><td>有效输入成功、非法输入 400、额外字段拒绝、响应字段明确；不把模拟身份版本对外发布</td></tr><tr><td>2. 建立真实闭环</td><td>接入账号认证、PostgreSQL、迁移与笔记 CRUD</td><td>重启后数据存在、他人无法访问、重复账号受约束、列表只包含本人数据</td></tr><tr><td>3. 验证真实边界</td><td>并发修改、依赖故障与正常下线</td><td>同版本并发仅一次更新成功、失败无部分写入、错误不泄密、资源按预期释放</td></tr></tbody></table><p>测试不要只验证“方法被调用”：纯规则写单元测试，Service 用替身验证业务分支；仓储与约束用独立 PostgreSQL 测试库做集成测试；E2E 覆盖 HTTP 状态、响应、身份与数据库结果。</p><p>至少验证：没有凭据的请求不能访问私有笔记，用户 A 不能操作用户 B 的记录，非法字段不能修改归属，两个同版本保存不能互相覆盖。数据库不可用时还要检查错误响应与日志，而不只是 happy path。</p><p>每个切片同步维护接口文档（如 Swagger / OpenAPI）、最小运行步骤、配置项说明和测试记录；涉及上线时再补充发布、回滚与恢复说明。实践完成后按<a href="/FE-prepare-interview/学习路线/实践记录模板">实践记录模板</a>补上代码链接、命令和实际结果，再写入<a href="https://fridolph.github.io/fridolph-blog/" target="_blank" rel="noreferrer">博客</a>。</p><h2 id="口述回顾" tabindex="-1">口述回顾 <a class="header-anchor" href="#口述回顾" aria-label="Permalink to &quot;口述回顾&quot;">​</a></h2><blockquote><p>我会先确认用户问题与最小闭环，再拆模块和接口契约。Nest 中用 Controller 处理 HTTP 边界，DTO 和 Pipe 校验输入，Guard 处理身份与访问资格，Service 表达业务规则，Repository 访问数据库。同时把数据约束、并发更新、测试和错误响应设计进去。第一版先跑通可验证的闭环，再根据真实瓶颈加入 Redis、权限扩展或 AI 能力。</p></blockquote><p>进阶时可以追问自己：为什么没有先加 Redis？怎样证明归属检查不会被绕过？一次更新结果未知时能不能重试？性能提升是靠指标证明，还是仅凭换了工具？</p><blockquote><p>来源：<a href="https://docs.nestjs.com/security/authentication" target="_blank" rel="noreferrer">NestJS：Authentication</a>、<a href="https://docs.nestjs.com/security/authorization" target="_blank" rel="noreferrer">NestJS：Authorization</a>、<a href="https://docs.nestjs.com/techniques/configuration" target="_blank" rel="noreferrer">NestJS：Configuration</a>、<a href="https://docs.nestjs.com/fundamentals/testing" target="_blank" rel="noreferrer">NestJS：Testing</a>、<a href="https://www.postgresql.org/docs/current/ddl-constraints.html" target="_blank" rel="noreferrer">PostgreSQL：Constraints</a>、<a href="https://cheatsheetseries.owasp.org/cheatsheets/REST_Security_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP：REST Security Cheat Sheet</a></p></blockquote>`,41)])])}const b=s(i,[["render",r]]);export{k as __pageData,b as default};
